import{_ as o,c as t,o as a,ag as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Browser & Sniffer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/browser.md","filePath":"guide/browser.md","lastUpdated":1791309864000}'),i={name:"guide/browser.md"};function n(s,e,d,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="browser-sniffer" tabindex="-1">Browser &amp; Sniffer <a class="header-anchor" href="#browser-sniffer" aria-label="Permalink to &quot;Browser &amp; Sniffer&quot;">​</a></h1><p>nPlyr includes a real <strong>multi-tab browser</strong> built on <code>WKWebView</code>, with a built-in <strong>media sniffer</strong>. It is how you capture a direct video link from a page that doesn&#39;t hand you one.</p><h2 id="the-browser" tabindex="-1">The browser <a class="header-anchor" href="#the-browser" aria-label="Permalink to &quot;The browser&quot;">​</a></h2><p>It is a Chrome-style tabbed browser:</p><ul><li><strong>Tabs</strong> — new / close / switch / reorder; drag a tab out to its own window (macOS).</li><li><strong>Navigation</strong> — back, forward, reload, and an address bar with autocomplete.</li><li><strong>Keyboard shortcuts</strong> — <code>⌘T</code> new tab, <code>⌘R</code> reload, <code>⌘[</code> / <code>⌘]</code> back / forward, <code>⌘L</code> focus address bar.</li><li><strong>Drag &amp; drop</strong> — drop a URL or text onto the window to open it.</li><li><strong>Pop-ups</strong> — <code>target=&quot;_blank&quot;</code> and <code>window.open</code> open in a new tab instead of a blocked window.</li><li><strong>Dialogs</strong> — JS <code>alert</code> / <code>confirm</code> / <code>prompt</code> are presented natively.</li><li><strong>Downloads</strong> — intercepted download links open in the in-app <strong>Downloads</strong> tab (<code>nplyr://downloads</code>).</li></ul><h2 id="how-the-sniffer-works" tabindex="-1">How the sniffer works <a class="header-anchor" href="#how-the-sniffer-works" aria-label="Permalink to &quot;How the sniffer works&quot;">​</a></h2><p>When a page loads, nPlyr injects a script that hooks:</p><ul><li><code>fetch</code> and <code>XMLHttpRequest</code>,</li><li><code>video.src</code> and <code>HTMLMediaElement</code> playback,</li><li><code>MediaSource</code> / <code>SourceBuffer.appendBuffer</code>.</li></ul><p>It also watches navigation via <code>WKNavigationDelegate</code> to catch server-side media redirects. Anything that looks like a media file — <strong>m3u8 / mp4 / flv / ts</strong> — is collected along with its <strong>request headers</strong> (referer, user-agent, cookies, auth) into a results drawer.</p><p>From the drawer you can:</p><ul><li><strong>Play</strong> the link immediately in the <a href="/guide/player.html">Player</a>.</li><li><strong>Download</strong> it (with its headers preserved) via <a href="/guide/downloads.html">Downloads</a>.</li><li><strong>Copy</strong> the URL and headers for use elsewhere.</li></ul><blockquote><p>The sniffer only captures links the page actually requests. Sites that wrap streams in a proprietary player or heavy DRM may not expose a clean direct link — for those, a <a href="/guide/miniapps.html">mini-program</a> that knows the source&#39;s API is the more reliable path.</p></blockquote><h2 id="limitations-known" tabindex="-1">Limitations (known) <a class="header-anchor" href="#limitations-known" aria-label="Permalink to &quot;Limitations (known)&quot;">​</a></h2><p>These are consciously deprioritized and may arrive in a later build:</p><ul><li>In-page right-click menu items (&quot;open link in new tab&quot;, &quot;download link&quot;) — the macOS <code>WKUIDelegate</code> context-menu hooks are iOS-only; nPlyr currently relies on the tab bar and toolbar instead.</li><li>In-page <strong>find</strong> (<code>⌘F</code>) — the WebKit API exists but the UI is not wired up yet.</li><li><strong>Print</strong> (<code>⌘P</code>) — WebKit supports it, but there is no menu item yet.</li><li><code>⌘W</code> closes the whole window when multiple tabs are open; per-tab close is planned.</li><li>Open tabs and history are <strong>not</strong> restored after a full app restart yet.</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The browser is a standard <code>WKWebView</code>. It does not inject trackers of its own. Cookies and local storage stay in the app&#39;s container. See <a href="/guide/privacy.html">Privacy</a> for the full picture.</p>',17)])])}const w=o(i,[["render",n]]);export{u as __pageData,w as default};
